// StackRightPickList.ts
// STAND-IN FOR BARCODE SCAN. A real picker's Lens would read the case's barcode when it is
// picked up. For the preview, the order is fixed: 30 cases in the warehouse system's
// heaviest-first sequence (5 layers). The learner should replace these lines with real order lines.
//
// Owns: the order (case data: name, weight, class, real size in cm, colour) and the LOAD PLAN,
// which is generated in code from the case sizes (not hand-placed): each layer is a centred grid
// of as many cases as fit the 116.5 cm pallet, and layers 2 and 4 are turned 90 degrees so the
// joints don't line up (interlock). Pure data/logic, no scene access.
// Must not: touch the scene, hold game state.
//
// Case sizes are W (x) x H (y) x D (z) in cm, in the case's own frame. Plan positions are in
// Pallet-local cm: x right, z toward the user (near edge = +z), y up from the floor.
// Pallet deck top is at y = 15.

export interface CaseSpec {
  key: string // used in scene object names, e.g. Case_03_Laundry
  name: string // printed on the case
  kg: number
  fragile: boolean // true = crushable, goes on top
  layer: number // 1..5
  size: vec3 // W x H x D, cm (case frame)
  color: vec4 // bright, light-saturated label colour (additive display: no dark colours)
}

export interface PlannedSlot {
  center: vec3 // Pallet-local centre of the case when placed
  layer: number // 1..5
  turned: boolean // true = turned 90 degrees about up (case W runs along pallet z)
  row: number // 0 = far row
  col: number // 0 = left column
}

export const PALLET_SIZE_CM = new vec3(116.5, 15, 116.5)
export const PALLET_DECK_Y = 15
export const HEIGHT_LIMIT_CM = 180
/** Layers that are turned 90 degrees relative to layer 1 (interlock). */
export const TURNED_LAYERS = [2, 4]

interface OrderLine {key: string, name: string, kg: number, fragile: boolean, layer: number,
  w: number, d: number, h: number, count: number, color: vec4}

// The order from devpost/design-brief.md, sizes W x D x H in cm, already heaviest first.
const ORDER_LINES: OrderLine[] = [
  {key: "Laundry", name: "LAUNDRY 4x4L", kg: 17, fragile: false, layer: 1, w: 38, d: 58, h: 30, count: 6, color: new vec4(0.6, 0.55, 1.0, 1)},
  {key: "Water", name: "WATER 24", kg: 14, fragile: false, layer: 2, w: 38, d: 58, h: 30, count: 6, color: new vec4(0.35, 0.75, 1.0, 1)},
  {key: "Tomatoes", name: "TOMATOES 24", kg: 10, fragile: false, layer: 3, w: 29, d: 58, h: 25, count: 8, color: new vec4(1.0, 0.4, 0.5, 1)},
  {key: "SoftDrink", name: "SOFT DRINK 24", kg: 9, fragile: false, layer: 4, w: 38, d: 58, h: 25, count: 6, color: new vec4(1.0, 0.6, 0.3, 1)},
  {key: "Eggs", name: "EGGS", kg: 10, fragile: true, layer: 5, w: 58, d: 58, h: 32, count: 1, color: new vec4(1.0, 0.92, 0.7, 1)},
  {key: "Bread", name: "BREAD", kg: 4, fragile: true, layer: 5, w: 58, d: 58, h: 32, count: 1, color: new vec4(1.0, 0.8, 0.5, 1)},
  {key: "Chips", name: "CHIPS", kg: 2, fragile: true, layer: 5, w: 58, d: 58, h: 32, count: 2, color: new vec4(0.5, 1.0, 0.6, 1)},
]

function buildOrder(): CaseSpec[] {
  const out: CaseSpec[] = []
  for (const l of ORDER_LINES) {
    for (let k = 0; k < l.count; k++) {
      out.push({key: l.key, name: l.name, kg: l.kg, fragile: l.fragile, layer: l.layer,
        size: new vec3(l.w, l.h, l.d), color: l.color})
    }
  }
  return out
}

export const ORDER: CaseSpec[] = buildOrder()
export const LAYER_COUNT = ORDER.reduce((m, c) => Math.max(m, c.layer), 0)

export function isTurnedLayer(layer: number): boolean {
  return TURNED_LAYERS.indexOf(layer) >= 0
}

/** Footprint on the pallet (x = across, z = depth) of a case in the planned orientation. */
export function footprint(spec: CaseSpec, turned: boolean): vec2 {
  return turned ? new vec2(spec.size.z, spec.size.x) : new vec2(spec.size.x, spec.size.z)
}

/** Ghost / placed size in pallet axes: the case size with x and z swapped when turned. */
export function plannedSize(spec: CaseSpec, turned: boolean): vec3 {
  return turned ? new vec3(spec.size.z, spec.size.y, spec.size.x) : spec.size
}

/**
 * Generates the slot plan for the whole order. For each layer: take the footprint of the layer's
 * case (turned 90 degrees on TURNED_LAYERS), fit as many as fit the pallet as a centred, tight
 * grid, fill far row to near row, left to right, and stack the layer on the previous layer's top.
 * Every case in a layer must share one footprint and height (out of scope: mixed layers).
 */
export function buildPlan(order: CaseSpec[]): PlannedSlot[] {
  const plan: PlannedSlot[] = []
  let bottom = PALLET_DECK_Y
  let i = 0
  while (i < order.length) {
    const layer = order[i].layer
    const first = order[i]
    const turned = isTurnedLayer(layer)
    const fp = footprint(first, turned)
    const cols = Math.floor(PALLET_SIZE_CM.x / fp.x)
    const rows = Math.floor(PALLET_SIZE_CM.z / fp.y)
    const x0 = -(cols * fp.x) / 2 + fp.x / 2
    const z0 = -(rows * fp.y) / 2 + fp.y / 2
    let n = 0
    while (i < order.length && order[i].layer === layer) {
      if (n >= cols * rows) {
        print("[StackRightPickList] ERROR: layer " + layer + " has more cases than fit (" + cols * rows + ")")
        break
      }
      const row = Math.floor(n / cols)
      const col = n % cols
      plan.push({
        center: new vec3(x0 + col * fp.x, bottom + first.size.y / 2, z0 + row * fp.y),
        layer, turned, row, col,
      })
      n++
      i++
    }
    while (i < order.length && order[i].layer === layer) i++ // skip any overflow
    bottom += first.size.y
  }
  return plan
}

export const PLAN: PlannedSlot[] = buildPlan(ORDER)

/** Top of the finished stack above the floor (cm). */
export const STACK_HEIGHT_CM = PLAN.reduce((m, s, k) => Math.max(m, s.center.y + ORDER[k].size.y / 2), PALLET_DECK_Y)

/** Number of cases in each layer, index = layer. */
export function layerCaseCount(layer: number): number {
  let n = 0
  for (const c of ORDER) if (c.layer === layer) n++
  return n
}

/** True when case i is the last one of its layer in the order. */
export function isLastOfLayer(i: number): boolean {
  return i < ORDER.length && (i === ORDER.length - 1 || ORDER[i + 1].layer !== ORDER[i].layer)
}

export function ghostTagText(i: number): string {
  return "Layer " + ORDER[i].layer + " · " + (i + 1) + " of " + ORDER.length + " · " + ORDER[i].kg + " kg"
}

export function layerDoneText(layer: number): string {
  return "Layer " + layer + " done.\nNext layer turns 90° so the joints don't line up."
}

// StackRightGeometry.ts
// Owns: tiny helpers that build primitive box visuals (pallet, shelves, cartons, ghost, arrow)
// from one 1 cm box mesh + one unlit material that is cloned per box. These are the obvious
// placeholder visuals; swap the boxMesh / baseMaterial @inputs on the controller to upgrade.
// Scale always lives on the leaf "Visual" child, never on a node that owns a collider.
// Must not: hold game state or create text.

export class BoxFactory {
  constructor(private mesh: RenderMesh, private baseMaterial: Material) {}

  makeMaterial(color: vec4, translucent: boolean): Material {
    const mat = this.baseMaterial.clone()
    mat.mainPass.baseColor = color
    if (translucent) {
      mat.mainPass.blendMode = BlendMode.Normal
      mat.mainPass.depthWrite = false
    }
    return mat
  }

  /** Creates a child SceneObject with a box visual of `size` cm centred at `localPos`. */
  makeBox(parent: SceneObject, name: string, size: vec3, localPos: vec3, color: vec4,
    translucent: boolean = false): RenderMeshVisual {
    const so = global.scene.createSceneObject(name)
    so.setParent(parent)
    const t = so.getTransform()
    t.setLocalPosition(localPos)
    t.setLocalScale(size)
    const rmv = so.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
    rmv.mesh = this.mesh
    rmv.mainMaterial = this.makeMaterial(color, translucent)
    return rmv
  }

  /** 12 thin bars outlining a box of `size` centred at the parent's origin. */
  makeWireBox(parent: SceneObject, name: string, size: vec3, thickness: number, color: vec4): SceneObject {
    const root = global.scene.createSceneObject(name)
    root.setParent(parent)
    const mat = this.makeMaterial(color, true)
    for (let i = 0; i < 12; i++) {
      const bar = global.scene.createSceneObject("Edge" + i)
      bar.setParent(root)
      const rmv = bar.createComponent("Component.RenderMeshVisual") as RenderMeshVisual
      rmv.mesh = this.mesh
      rmv.mainMaterial = mat
    }
    BoxFactory.layoutWireBox(root, size, thickness)
    return root
  }

  static layoutWireBox(root: SceneObject, size: vec3, th: number): void {
    const hx = size.x / 2, hy = size.y / 2, hz = size.z / 2
    const specs: [vec3, vec3][] = []
    for (const sy of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(0, sy * hy, sz * hz), new vec3(size.x + th, th, th)])
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) specs.push([new vec3(sx * hx, 0, sz * hz), new vec3(th, size.y + th, th)])
    for (const sx of [-1, 1]) for (const sy of [-1, 1]) specs.push([new vec3(sx * hx, sy * hy, 0), new vec3(th, th, size.z + th)])
    for (let i = 0; i < 12 && i < root.getChildrenCount(); i++) {
      const t = root.getChild(i).getTransform()
      t.setLocalPosition(specs[i][0])
      t.setLocalScale(specs[i][1])
    }
  }
}

// StackRightController.ts
// Stack Right: pallet-building trainer. Owns ALL game state (case due now, placed count,
// mistakes, timer, pick-face queue) and the rules: ghost on grab (turned on layers 2 and 4),
// snap within 15 cm with the planned rotation, dropped on the pallet but off the ghost ->
// slide back + red "overhang" / "gap" tip + mistake, released off the pallet -> slide back
// (no mistake), "layer done" note, completion card, reset, glow on the case due now,
// off-view arrow + chime, height-limit outline.
//
// Expects (@input): the authored Pallet, ShelfBay, PickList root (cases are created at runtime
// under it; any authored children are reused for the first ones), Ghost, OffViewArrow, ResetPost
// SceneObjects; the four StackRightLabelUI panels (GhostTag, Counter, TipText, CompletionCard);
// the StackRightResetButtonUI; the 1 cm box mesh and unlit base material used for every
// placeholder visual.
//
// Pick face: only the next QUEUE_SIZE not-yet-placed cases are shown, on the lower shelf, the one
// due now in the slot nearest the pallet. The rest are disabled until they enter the queue. Only
// the case due now is interactable.
//
// Real SIK grab/release events and the LEAF test hooks (simulateGrab / simulateRelease) run
// through the same handleGrab / handleRelease code path.
// Must not: build UI text itself (labels live in the *UI.ts modules), or plan slots (PickList does).
import {Interactable} from "SpectaclesInteractionKit.lspkg/Components/Interaction/Interactable/Interactable"
import {InteractableManipulation} from "SpectaclesInteractionKit.lspkg/Components/Interaction/InteractableManipulation/InteractableManipulation"
import WorldCameraFinderProvider from "SpectaclesInteractionKit.lspkg/Providers/CameraProvider/WorldCameraFinderProvider"
import {
  ORDER, PLAN, CaseSpec, PALLET_SIZE_CM, PALLET_DECK_Y, HEIGHT_LIMIT_CM, LAYER_COUNT, STACK_HEIGHT_CM,
  footprint, plannedSize, ghostTagText, layerDoneText, isLastOfLayer,
} from "./StackRightPickList"
import {BoxFactory} from "./StackRightGeometry"
import {StackRightLabelUI} from "./StackRightLabelUI"
import {StackRightResetButtonUI} from "./StackRightResetButtonUI"
import {StackRightCartonLabelUI} from "./StackRightCartonLabelUI"

const SFX_CHIME = requireAsset("../GeneratedSFX/StackRightChime.wav") as AudioTrackAsset
const SFX_SNAP = requireAsset("../GeneratedSFX/StackRightSnap.wav") as AudioTrackAsset
const SFX_MISTAKE = requireAsset("../GeneratedSFX/StackRightMistake.wav") as AudioTrackAsset
const SFX_COMPLETE = requireAsset("../GeneratedSFX/StackRightComplete.wav") as AudioTrackAsset

const CHIME_COOLDOWN_SEC = 6
const OFF_PALLET_MARGIN_CM = 5
/** A drop whose footprint hangs further than this over the pallet edge is an overhang. */
const OVERHANG_TOLERANCE_CM = 2
const QUEUE_SIZE = 4
/** Lower shelf of the bay (ShelfBay-local): top of the board, and the 4 queue slots along it. */
const SHELF_TOP_Y = 40
const QUEUE_FRONT_Z = 90 // slot nearest the pallet (and the user)
const QUEUE_PITCH_Z = -60 // each later queue slot is further along the shelf

// Two lines (break at the sentence) so the tip stays narrower than the pallet in view.
export const TIP_OVERHANG = "Overhang.\nKeep it inside the edge."
export const TIP_GAP = "That leaves a gap.\nDrop it on the ghost."

interface CaseState {
  index: number
  spec: CaseSpec
  so: SceneObject
  home: vec3
  placed: boolean
  grabbed: boolean
  returning: boolean
  returnFrom: vec3
  returnT: number
  hovered: boolean
  interactable: Interactable
  manip: InteractableManipulation
  bodyMat: Material
  bodyColor: vec4
  glow: SceneObject
  glowMat: Material
}

@component
export class StackRightController extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightController – pallet-building trainer rules + test API</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">References</span>')
  @ui.group_start("References")
  @input
  @hint("Pallet root: on the floor, origin at the centre of its footprint")
  pallet: SceneObject
  @input
  @hint("Shelf bay root: on the floor to the user's right")
  shelfBay: SceneObject
  @input
  @hint("PickList (stand-in for barcode scan): cases are created under it at runtime, in order")
  pickList: SceneObject
  @input
  @hint("Ghost case root (child of Pallet)")
  ghost: SceneObject
  @input
  @hint("Arrow on the pallet edge that points at the case due now when it is out of view")
  offViewArrow: SceneObject
  @input
  @hint("Short post under the Reset button")
  resetPost: SceneObject
  @input
  @hint("Tag on the ghost: 'Layer N · K of 30 · kg'")
  ghostTag: StackRightLabelUI
  @input
  @hint("'Layer N · K / 30' counter on the pallet's near edge")
  counter: StackRightLabelUI
  @input
  @hint("Red tip (mistakes) / white note (layer done) shown on the pallet for a few seconds")
  tipText: StackRightLabelUI
  @input
  @hint("Completion card: cases, layers, height, time, mistakes, 'Wrap and label'")
  completionCard: StackRightLabelUI
  @input
  @hint("Reset pallet button")
  resetButton: StackRightResetButtonUI
  @input
  @hint("1 cm box mesh used for every placeholder visual")
  boxMesh: RenderMesh
  @input
  @hint("Unlit material cloned for every placeholder visual")
  baseMaterial: Material
  @ui.group_end

  @ui.separator
  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Release within this horizontal distance (cm) of the ghost to snap")
  @widget(new SliderWidget(5, 40, 1))
  snapDistanceCm: number = 15

  @input
  @hint("Mouse-friendly allowance: how far ABOVE the ghost (cm) a release still snaps. Below, the limit is snapDistanceCm.")
  @widget(new SliderWidget(0, 120, 1))
  dropHeightAllowanceCm: number = 60

  @input
  @hint("How long the red tip / layer note stays on the pallet (s)")
  @widget(new SliderWidget(1, 10, 0.5))
  tipDurationSec: number = 4

  @input
  @hint("Place the floor this far below the user's eyes at start (cm). The work area root (this object's parent) is moved to camera.y - eyeHeightCm.")
  @widget(new SliderWidget(100, 200, 1))
  eyeHeightCm: number = 150

  @input("vec4", "{0.6,1,1,0.3}")
  @hint("Ghost fill colour (pale cyan, about 30% fill)")
  @widget(new ColorWidget())
  ghostColor: vec4 = new vec4(0.6, 1, 1, 0.3)

  @input("vec4", "{1,1,0.55,0.35}")
  @hint("Soft glow around the case due now on the pick face")
  @widget(new ColorWidget())
  glowColor: vec4 = new vec4(1, 1, 0.55, 0.35)

  @input("vec4", "{1,0.35,0.35,1}")
  @hint("Tip text colour (bright red, not dark)")
  @widget(new ColorWidget())
  tipColor: vec4 = new vec4(1, 0.35, 0.35, 1)

  @input("vec4", "{1,1,1,1}")
  @hint("Layer-done note text colour")
  @widget(new ColorWidget())
  noteColor: vec4 = new vec4(1, 1, 1, 1)

  @input("vec4", "{0.85,0.95,1,0.7}")
  @hint("Height-limit outline colour (thin, pale)")
  @widget(new ColorWidget())
  heightLimitColor: vec4 = new vec4(0.85, 0.95, 1, 0.7)
  @ui.group_end

  @ui.separator
  @ui.label('<span style="color: #60A5FA;">Debug</span>')
  @ui.group_start("Debug")
  @input
  @hint("Print grab/release decisions to the log")
  debugLogs: boolean = false
  @ui.group_end

  // ---- state (single owner) ----
  private cases: CaseState[] = []
  private nextIndex = 0
  private placedCount = 0
  private mistakes = 0
  private overhangMistakes = 0
  private gapMistakes = 0
  private complete = false
  private grabbedIndex = -1
  private startTime = -1
  private finishTime = -1
  private tipHideAt = -1
  private tipKind = "" // "" | "overhang" | "gap" | "layer"
  private ghostTagString = ""
  private tipString = ""
  private completionString = ""
  private arrowVisible = false
  private nextInView = true
  private lastChimeAt = -100
  private wasOutOfView = false

  private factory: BoxFactory
  private ghostFill: SceneObject
  private ghostWire: SceneObject
  private heightLimit: SceneObject
  private palletT: Transform
  private returnDuration = 0.6
  private audio: {[k: string]: AudioComponent} = {}
  private ready = false

  onAwake(): void {
    if (!this.validateRefs()) return
    this.factory = new BoxFactory(this.boxMesh, this.baseMaterial)
    this.palletT = this.pallet.getTransform()
    this.alignFloorToCamera()
    this.buildPalletVisual()
    this.buildShelfVisual()
    this.buildResetPostVisual()
    this.buildHeightLimit()
    this.buildGhost()
    this.buildArrow()
    this.buildCases()
    this.buildAudio()

    this.createEvent("OnStartEvent").bind(() => this.onStart())
    this.createEvent("UpdateEvent").bind(() => this.onUpdate())
  }

  private onStart(): void {
    for (const c of this.cases) {
      const i = c.index
      c.manip.onManipulationStart.add(() => this.handleGrab(i))
      c.manip.onManipulationEnd.add(() => this.handleRelease(i, c.so.getTransform().getWorldPosition()))
      c.interactable.onHoverEnter.add(() => this.setHover(i, true))
      c.interactable.onHoverExit.add(() => this.setHover(i, false))
    }
    this.resetButton.onReset.add(() => this.reset())
    this.ready = true
    this.reset()
    const cam = WorldCameraFinderProvider.getInstance()
    print("[StackRight] ready. " + this.cases.length + " cases, " + LAYER_COUNT + " layers, stack " + STACK_HEIGHT_CM +
      " cm. camera = " + cam.getTransform().getWorldPosition() + " pallet = " + this.getPalletWorldPosition() +
      " shelf = " + this.getShelfWorldPosition())
  }

  // =====================================================================================
  // Public API (used by the scene and by LEAF tests)
  // =====================================================================================
  getPlacedCount(): number { return this.placedCount }
  getMistakes(): number { return this.mistakes }
  getOverhangMistakes(): number { return this.overhangMistakes }
  getGapMistakes(): number { return this.gapMistakes }
  /** Index into the order of the case due now (30 when complete). */
  getNextIndex(): number { return this.nextIndex }
  isComplete(): boolean { return this.complete }
  isGhostVisible(): boolean { return this.ghost.enabled }
  getGhostTagText(): string { return this.ghostTag.isVisible() ? this.ghostTagString : "" }
  isGhostTagVisible(): boolean { return this.ghostTag.isVisible() }
  /** Ghost box size in Pallet axes (x across, z depth). */
  getGhostSize(): vec3 { return this.ghostFill.getTransform().getLocalScale() }
  getTipText(): string { return this.tipString }
  /** "overhang" | "gap" | "layer" | "" */
  getTipKind(): string { return this.tipKind }
  isTipVisible(): boolean { return this.tipText.isVisible() }
  isCompletionVisible(): boolean { return this.completionCard.isVisible() }
  getCompletionText(): string { return this.completionString }
  getCounterText(): string { return this.counter.getText() }
  isArrowVisible(): boolean { return this.arrowVisible }
  isNextCaseInView(): boolean { return this.nextInView }
  getCaseCount(): number { return this.cases.length }
  getCaseName(i: number): string { return this.cases[i] ? this.cases[i].so.name : "" }
  isCasePlaced(i: number): boolean { return !!this.cases[i] && this.cases[i].placed }
  isCaseReturning(i: number): boolean { return !!this.cases[i] && this.cases[i].returning }
  isCaseGlowing(i: number): boolean { return !!this.cases[i] && this.cases[i].glow.enabled }
  isCaseShown(i: number): boolean { return !!this.cases[i] && this.cases[i].so.enabled }
  isCaseInteractable(i: number): boolean { return !!this.cases[i] && this.cases[i].interactable.enabled }
  /** Queue position of case i on the pick face (0 = due now), or -1 if placed / not in the queue. */
  getQueuePosition(i: number): number {
    if (!this.cases[i] || this.cases[i].placed) return -1
    const q = i - this.nextIndex
    return q >= 0 && q < QUEUE_SIZE ? q : -1
  }
  getQueueSize(): number { return QUEUE_SIZE }
  getQueueSlotWorldPosition(q: number, i: number): vec3 { return this.queueHome(q, this.cases[i].spec) }
  getGrabbedIndex(): number { return this.grabbedIndex }
  getGhostWorldPosition(): vec3 { return this.ghost.getTransform().getWorldPosition() }
  /** Where case i snaps to on the pallet (centre of the case). */
  getSlotWorldPosition(i: number): vec3 { return this.palletT.getWorldTransform().multiplyPoint(PLAN[i].center) }
  getSlotWorldRotation(i: number): quat { return this.plannedRotation(i) }
  isSlotTurned(i: number): boolean { return PLAN[i].turned }
  getSlotLayer(i: number): number { return PLAN[i].layer }
  getCaseWorldPosition(i: number): vec3 { return this.cases[i].so.getTransform().getWorldPosition() }
  getCaseWorldRotation(i: number): quat { return this.cases[i].so.getTransform().getWorldRotation() }
  getCaseHomePosition(i: number): vec3 { return this.cases[i].home }
  getPalletWorldPosition(): vec3 { return this.palletT.getWorldPosition() }
  getPalletWorldTransform(): mat4 { return this.palletT.getWorldTransform() }
  getShelfWorldPosition(): vec3 { return this.shelfBay.getTransform().getWorldPosition() }
  getCameraWorldPosition(): vec3 { return WorldCameraFinderProvider.getInstance().getTransform().getWorldPosition() }
  /** Floor height (world y): the pallet root sits on the floor. */
  getFloorWorldY(): number { return this.palletT.getWorldPosition().y }
  getHeightLimitWorldY(): number { return this.heightLimit.getTransform().getWorldPosition().y }
  isHeightLimitVisible(): boolean { return this.heightLimit.enabled && this.heightLimit.isEnabledInHierarchy }
  /** Top of the placed stack above the floor (cm). */
  getStackTopCm(): number { return this.stackTop() }

  /** Test hook: same code path as a real SIK grab. */
  simulateGrab(caseIndex: number): void {
    this.handleGrab(caseIndex)
  }

  /** Test hook: moves the case to worldPos, then runs the same code path as a real SIK release. */
  simulateRelease(caseIndex: number, worldPos: vec3): void {
    const c = this.cases[caseIndex]
    if (!c) return
    if (!c.placed) c.so.getTransform().setWorldPosition(worldPos)
    this.handleRelease(caseIndex, worldPos)
  }

  /** Test hook: same path as pinching the Reset button. */
  pressReset(): void {
    this.resetButton.press()
  }

  /** Clears the pallet and restarts the order: the first 4 cases on the pick face. */
  reset(): void {
    for (const c of this.cases) {
      c.placed = false
      c.grabbed = false
      c.returning = false
      c.hovered = false
      c.so.getTransform().setWorldRotation(quat.quatIdentity())
      c.bodyMat.mainPass.baseColor = c.bodyColor
    }
    this.nextIndex = 0
    this.placedCount = 0
    this.mistakes = 0
    this.overhangMistakes = 0
    this.gapMistakes = 0
    this.complete = false
    this.grabbedIndex = -1
    this.startTime = -1
    this.finishTime = -1
    this.completionString = ""
    this.ghostTagString = ""
    this.hideTip()
    this.ghost.enabled = false
    this.ghostTag.setVisible(false)
    this.completionCard.setVisible(false)
    this.wasOutOfView = false
    this.layoutQueue(false)
    this.updateCounter()
    this.updateStackFollowers()
    this.log("reset")
  }

  // =====================================================================================
  // Rules
  // =====================================================================================
  private handleGrab(i: number): void {
    const c = this.cases[i]
    if (!c || c.placed || this.complete || i !== this.nextIndex) return
    c.grabbed = true
    c.returning = false
    this.grabbedIndex = i
    if (this.startTime < 0) this.startTime = getTime()
    this.showGhostFor(i)
    this.updateGlow()
    this.log("grab " + c.so.name + " (ghost shown, layer " + PLAN[i].layer + (PLAN[i].turned ? ", turned 90" : "") + ")")
  }

  private handleRelease(i: number, worldPos: vec3): void {
    const c = this.cases[i]
    if (!c || c.placed) return
    c.grabbed = false
    if (this.grabbedIndex === i) this.grabbedIndex = -1
    this.hideGhost()

    if (this.complete || i !== this.nextIndex) {
      this.sendHome(c)
      this.updateGlow()
      return
    }

    const local = this.palletT.getInvertedWorldTransform().multiplyPoint(worldPos)
    const halfPallet = PALLET_SIZE_CM.x / 2
    const reach = halfPallet + OFF_PALLET_MARGIN_CM
    const onPallet = Math.abs(local.x) <= reach && Math.abs(local.z) <= reach && local.y >= -20 && local.y <= 250

    const slot = PLAN[i].center
    const dx = local.x - slot.x
    const dz = local.z - slot.z
    const dy = local.y - slot.y
    const horiz = Math.sqrt(dx * dx + dz * dz)
    if (horiz <= this.snapDistanceCm && dy >= -this.snapDistanceCm && dy <= Math.max(this.snapDistanceCm, this.dropHeightAllowanceCm)) {
      this.place(c)
    } else if (onPallet) {
      // Would any part of the case (planned orientation, centred on the drop point) hang over the edge?
      const fp = footprint(c.spec, PLAN[i].turned)
      const over = Math.max(Math.abs(local.x) + fp.x / 2, Math.abs(local.z) + fp.y / 2) - halfPallet
      if (over > OVERHANG_TOLERANCE_CM) this.mistake(c, "overhang", TIP_OVERHANG)
      else this.mistake(c, "gap", TIP_GAP)
    } else {
      this.log("released " + c.so.name + " off the pallet: back to the pick face, no mistake")
      this.sendHome(c)
    }
    this.updateGlow()
  }

  private place(c: CaseState): void {
    const i = c.index
    const t = c.so.getTransform()
    t.setWorldPosition(this.getSlotWorldPosition(i))
    t.setWorldRotation(this.plannedRotation(i))
    c.placed = true
    c.returning = false
    c.bodyMat.mainPass.baseColor = c.bodyColor
    this.placedCount++
    this.nextIndex++
    this.play("snap")
    this.log("placed " + c.so.name + " -> " + this.placedCount + "/" + this.cases.length)
    if (this.nextIndex >= this.cases.length) {
      this.finish()
    } else if (isLastOfLayer(i)) {
      this.showTip("layer", layerDoneText(PLAN[i].layer), this.noteColor)
    }
    this.layoutQueue(true)
    this.updateCounter()
    this.updateStackFollowers()
  }

  private mistake(c: CaseState, kind: string, tip: string): void {
    this.mistakes++
    if (kind === "overhang") this.overhangMistakes++
    else if (kind === "gap") this.gapMistakes++
    this.showTip(kind, tip, this.tipColor)
    this.play("mistake")
    this.log("mistake #" + this.mistakes + " (" + c.so.name + "): " + tip.replace(/\n/g, " "))
    this.sendHome(c)
  }

  private showTip(kind: string, msg: string, color: vec4): void {
    this.tipKind = kind
    this.tipString = msg
    this.tipText.setText(msg)
    this.tipText.setTextColor(color)
    this.tipText.setVisible(true)
    this.tipHideAt = getTime() + this.tipDurationSec
  }

  private hideTip(): void {
    this.tipHideAt = -1
    this.tipKind = ""
    this.tipString = ""
    this.tipText.setVisible(false)
  }

  // " (2 overhang · 1 gap)" so the learner sees which rule they broke; empty when there were none.
  private mistakeBreakdown(): string {
    const parts: string[] = []
    if (this.overhangMistakes > 0) parts.push(this.overhangMistakes + " overhang")
    if (this.gapMistakes > 0) parts.push(this.gapMistakes + " gap")
    return parts.length > 0 ? " (" + parts.join(" · ") + ")" : ""
  }

  private finish(): void {
    this.complete = true
    this.finishTime = getTime()
    const secs = Math.max(0, Math.round(this.finishTime - (this.startTime < 0 ? this.finishTime : this.startTime)))
    const mm = Math.floor(secs / 60)
    const ss = secs % 60
    const time = mm + ":" + (ss < 10 ? "0" : "") + ss
    const height = Math.round(this.stackTop())
    this.completionString = "Pallet done! " + this.cases.length + " cases · " + LAYER_COUNT + " layers · " + height + " cm\n" +
      "Time " + time + " · Mistakes " + this.mistakes + this.mistakeBreakdown() + "\nWrap and label the pallet."
    this.completionCard.setText(this.completionString)
    // Above the 180 cm line, not across it, and larger so it reads from where the picker stands.
    const cardT = this.completionCard.sceneObject.getTransform()
    cardT.setLocalPosition(new vec3(0, Math.max(this.stackTop() + 24, HEIGHT_LIMIT_CM + 30), 20))
    cardT.setLocalScale(new vec3(1.5, 1.5, 1.5))
    this.completionCard.setVisible(true)
    this.hideTip()
    this.arrowVisible = false
    this.offViewArrow.enabled = false
    this.play("complete")
  }

  private sendHome(c: CaseState): void {
    c.returning = true
    c.returnT = 0
    c.returnFrom = c.so.getTransform().getWorldPosition()
  }

  private showGhostFor(i: number): void {
    const spec = this.cases[i].spec
    const slot = PLAN[i]
    const size = plannedSize(spec, slot.turned)
    this.ghost.getTransform().setLocalPosition(slot.center)
    this.ghostFill.getTransform().setLocalScale(size)
    BoxFactory.layoutWireBox(this.ghostWire, size.add(new vec3(0.6, 0.6, 0.6)), 0.8)
    this.ghost.enabled = true
    this.ghostTagString = ghostTagText(i)
    this.ghostTag.setText(this.ghostTagString)
    this.ghostTag.sceneObject.getTransform().setLocalPosition(
      new vec3(slot.center.x, slot.center.y + size.y / 2 + 7, slot.center.z + size.z / 2 + 3))
    this.ghostTag.setVisible(true)
  }

  private hideGhost(): void {
    this.ghost.enabled = false
    this.ghostTag.setVisible(false)
  }

  /** Pallet rotation, plus 90 degrees about up when the slot is turned. */
  private plannedRotation(i: number): quat {
    const r = this.palletT.getWorldRotation()
    return PLAN[i].turned ? r.multiply(quat.angleAxis(Math.PI / 2, vec3.up())) : r
  }

  private stackTop(): number {
    if (this.placedCount === 0) return PALLET_DECK_Y
    const k = this.placedCount - 1
    return PLAN[k].center.y + this.cases[k].spec.size.y / 2
  }

  /** World position of queue slot q (0 = due now, nearest the pallet) on the lower shelf. */
  private queueHome(q: number, spec: CaseSpec): vec3 {
    const local = new vec3(0, SHELF_TOP_Y + spec.size.y / 2, QUEUE_FRONT_Z + q * QUEUE_PITCH_Z)
    return this.shelfBay.getTransform().getWorldTransform().multiplyPoint(local)
  }

  /**
   * Shows the next QUEUE_SIZE not-yet-placed cases on the pick face and hides the rest.
   * animate = true: cases already on the shelf slide up to their new slot; a case entering the
   * queue appears at the back.
   */
  private layoutQueue(animate: boolean): void {
    for (const c of this.cases) {
      if (c.placed) {
        c.so.enabled = true
        continue
      }
      const q = c.index - this.nextIndex
      const inQueue = q >= 0 && q < QUEUE_SIZE
      const wasShown = c.so.enabled
      c.so.enabled = inQueue
      if (!inQueue) {
        c.returning = false
        continue
      }
      c.home = this.queueHome(q, c.spec)
      if (animate && wasShown) {
        if (!c.grabbed) this.sendHome(c)
      } else {
        c.returning = false
        c.so.getTransform().setWorldPosition(c.home)
        c.so.getTransform().setWorldRotation(quat.quatIdentity())
      }
    }
    this.updateInteractivity()
    this.updateGlow()
  }

  /** Only the case due now can be grabbed. */
  private updateInteractivity(): void {
    for (const c of this.cases) {
      const on = !this.complete && !c.placed && c.index === this.nextIndex
      c.interactable.enabled = on
      c.manip.enabled = on
      if (!on && c.hovered) this.setHover(c.index, false)
    }
  }

  private updateCounter(): void {
    const layer = PLAN[Math.min(this.nextIndex, PLAN.length - 1)].layer
    this.counter.setText("Layer " + layer + " · " + this.placedCount + " / " + this.cases.length)
  }

  /** Keeps the tip/note and the off-view arrow just above the current stack top. */
  private updateStackFollowers(): void {
    const top = this.stackTop()
    this.tipText.sceneObject.getTransform().setLocalPosition(new vec3(0, Math.max(75, top + 28), top > 50 ? 30 : 62))
    this.offViewArrow.getTransform().setLocalPosition(new vec3(35, top + 3, 52))
  }

  private updateGlow(): void {
    for (const c of this.cases) {
      c.glow.enabled = !this.complete && c.index === this.nextIndex && !c.grabbed && !c.placed
    }
  }

  private setHover(i: number, on: boolean): void {
    const c = this.cases[i]
    if (!c || c.placed) return
    c.hovered = on
    const k = on ? 0.4 : 0
    const col = c.bodyColor
    c.bodyMat.mainPass.baseColor = new vec4(col.x + (1 - col.x) * k, col.y + (1 - col.y) * k, col.z + (1 - col.z) * k, 1)
  }

  // =====================================================================================
  // Per-frame: slide-back / queue slide, tip timeout, glow pulse, off-view arrow + chime
  // =====================================================================================
  private onUpdate(): void {
    if (!this.ready) return
    const now = getTime()
    const dt = getDeltaTime()

    for (const c of this.cases) {
      if (!c.returning) continue
      c.returnT = Math.min(1, c.returnT + dt / this.returnDuration)
      const e = 1 - Math.pow(1 - c.returnT, 3)
      c.so.getTransform().setWorldPosition(vec3.lerp(c.returnFrom, c.home, e))
      if (c.returnT >= 1) {
        c.returning = false
        c.so.getTransform().setWorldRotation(quat.quatIdentity())
      }
    }

    if (this.tipHideAt > 0 && now >= this.tipHideAt) {
      this.hideTip()
    }

    const pulse = 0.65 + 0.35 * Math.sin(now * 3)
    for (const c of this.cases) {
      if (c.glow.enabled) {
        c.glowMat.mainPass.baseColor = new vec4(this.glowColor.x, this.glowColor.y, this.glowColor.z, this.glowColor.w * pulse)
      }
    }

    this.updateOffView(now)
  }

  private updateOffView(now: number): void {
    if (this.complete || this.nextIndex >= this.cases.length) {
      this.arrowVisible = false
      this.offViewArrow.enabled = false
      return
    }
    const next = this.cases[this.nextIndex]
    const target = next.so.getTransform().getWorldPosition()
    const cam = WorldCameraFinderProvider.getInstance()
    this.nextInView = cam.inFoV(target)
    const show = !this.nextInView && this.grabbedIndex < 0
    this.arrowVisible = show
    this.offViewArrow.enabled = show
    if (show) {
      const from = this.offViewArrow.getTransform().getWorldPosition()
      const dx = target.x - from.x
      const dz = target.z - from.z
      const yaw = Math.atan2(-dz, dx) // arrow geometry points along local +X
      this.offViewArrow.getTransform().setWorldRotation(quat.angleAxis(yaw, vec3.up()))
      if (!this.wasOutOfView && now - this.lastChimeAt >= CHIME_COOLDOWN_SEC) {
        this.lastChimeAt = now
        this.play("chime")
      }
    }
    this.wasOutOfView = show
  }

  // =====================================================================================
  // Build (placeholder visuals on authored roots)
  // =====================================================================================
  /** Puts the floor (work-area root) eyeHeightCm below the camera's current height. */
  private alignFloorToCamera(): void {
    const root = this.sceneObject.getParent()
    if (!root) return
    const cam = WorldCameraFinderProvider.getInstance()
    if (!cam) return
    const camY = cam.getTransform().getWorldPosition().y
    const t = root.getTransform()
    const p = t.getWorldPosition()
    t.setWorldPosition(new vec3(p.x, camY - this.eyeHeightCm, p.z))
    this.log("floor aligned: camera y = " + camY + ", floor y = " + (camY - this.eyeHeightCm))
  }

  private buildPalletVisual(): void {
    const v = global.scene.createSceneObject("PalletVisual")
    v.setParent(this.pallet)
    const wood = new vec4(1.0, 0.8, 0.5, 1)
    const woodLight = new vec4(1.0, 0.88, 0.65, 1)
    const S = PALLET_SIZE_CM.x
    // three bearers along z (bottom 11 cm)
    for (const x of [-S / 2 + 5, 0, S / 2 - 5]) {
      this.factory.makeBox(v, "Bearer", new vec3(10, 11, S), new vec3(x, 5.5, 0), wood)
    }
    // seven deck boards along x (top 4 cm), square to the edges
    const n = 7
    const bw = 13.5
    const gap = (S - n * bw) / (n - 1)
    for (let k = 0; k < n; k++) {
      const z = -S / 2 + bw / 2 + k * (bw + gap)
      this.factory.makeBox(v, "Deck", new vec3(S, 4, bw), new vec3(0, 13, z), woodLight)
    }
  }

  private buildShelfVisual(): void {
    const v = global.scene.createSceneObject("ShelfVisual")
    v.setParent(this.shelfBay)
    const post = new vec4(0.45, 0.65, 1.0, 1)
    const beam = new vec4(1.0, 0.62, 0.25, 1)
    const board = new vec4(0.85, 0.88, 0.95, 1)
    // 240 W (along z) x 60 D (along x); shelf tops at 40 and 100 cm
    for (const x of [-28, 28]) for (const z of [-118, 118]) {
      this.factory.makeBox(v, "Post", new vec3(4, 150, 4), new vec3(x, 75, z), post)
    }
    for (const top of [SHELF_TOP_Y, 100]) {
      this.factory.makeBox(v, "Board", new vec3(60, 3, 240), new vec3(0, top - 1.5, 0), board)
      this.factory.makeBox(v, "Beam", new vec3(3, 6, 240), new vec3(-31.5, top - 3, 0), beam)
    }
  }

  private buildResetPostVisual(): void {
    this.factory.makeBox(this.resetPost, "PostVisual", new vec3(4, 84, 4), new vec3(0, 42, 0), new vec4(0.75, 0.8, 0.9, 1))
  }

  /** Thin pale rectangle around the pallet footprint at HEIGHT_LIMIT_CM above the floor, plus a label. */
  private buildHeightLimit(): void {
    this.heightLimit = global.scene.createSceneObject("HeightLimit")
    this.heightLimit.setParent(this.pallet)
    this.heightLimit.getTransform().setLocalPosition(new vec3(0, HEIGHT_LIMIT_CM, 0))
    const S = PALLET_SIZE_CM.x
    const th = 0.8
    for (const sz of [-1, 1]) {
      this.factory.makeBox(this.heightLimit, "EdgeX", new vec3(S + th, th, th), new vec3(0, 0, sz * S / 2), this.heightLimitColor, true)
    }
    for (const sx of [-1, 1]) {
      this.factory.makeBox(this.heightLimit, "EdgeZ", new vec3(th, th, S + th), new vec3(sx * S / 2, 0, 0), this.heightLimitColor, true)
    }
    const label = global.scene.createSceneObject("HeightLimitLabel")
    label.setParent(this.heightLimit)
    // Front-right corner, so it never sits behind the centred completion card.
    label.getTransform().setLocalPosition(new vec3(S / 2, 3, S / 2))
    const t = label.createComponent("Component.Text") as Text
    t.text = "Height limit " + HEIGHT_LIMIT_CM + " cm"
    t.size = 110
    t.depthTest = true
    t.textFill.color = new vec4(this.heightLimitColor.x, this.heightLimitColor.y, this.heightLimitColor.z, 1)
    t.horizontalAlignment = HorizontalAlignment.Right
    t.verticalAlignment = VerticalAlignment.Bottom
    t.horizontalOverflow = HorizontalOverflow.Overflow
    t.layoutRect = Rect.create(-60, 0, 0, 4)
  }

  private buildGhost(): void {
    this.ghostFill = this.factory.makeBox(this.ghost, "GhostFill", new vec3(1, 1, 1), vec3.zero(), this.ghostColor, true).getSceneObject()
    this.ghostWire = this.factory.makeWireBox(this.ghost, "GhostOutline", new vec3(10, 10, 10), 0.8,
      new vec4(this.ghostColor.x, this.ghostColor.y, this.ghostColor.z, 0.95))
    this.ghost.enabled = false
  }

  private buildArrow(): void {
    const yellow = new vec4(1, 0.95, 0.3, 1)
    // flat arrow on the pallet edge, pointing along local +X
    this.factory.makeBox(this.offViewArrow, "Shaft", new vec3(16, 1.5, 4), new vec3(-4, 0, 0), yellow)
    const head1 = this.factory.makeBox(this.offViewArrow, "HeadA", new vec3(10, 1.5, 3.5), new vec3(5.5, 0, -2.7), yellow).getSceneObject()
    // each head bar leans in toward the tip (+X), so the pair forms a ">" rather than a fork
    head1.getTransform().setLocalRotation(quat.angleAxis(-0.7, vec3.up()))
    const head2 = this.factory.makeBox(this.offViewArrow, "HeadB", new vec3(10, 1.5, 3.5), new vec3(5.5, 0, 2.7), yellow).getSceneObject()
    head2.getTransform().setLocalRotation(quat.angleAxis(0.7, vec3.up()))
    this.offViewArrow.enabled = false
  }

  /** All cases of the order, under PickList: authored children are reused, the rest created. */
  private buildCases(): void {
    for (let i = 0; i < ORDER.length; i++) {
      const spec = ORDER[i]
      let so: SceneObject
      if (i < this.pickList.getChildrenCount()) {
        so = this.pickList.getChild(i)
      } else {
        so = global.scene.createSceneObject("Case")
        so.setParent(this.pickList)
      }
      so.name = "Case_" + (i < 10 ? "0" : "") + i + "_" + spec.key
      // Neighbouring cases in a layer alternate between two shades so the joints read clearly.
      const slot = PLAN[i]
      const k = (slot.row + slot.col) % 2 === 0 ? 0 : 0.3
      const bodyColor = new vec4(spec.color.x + (1 - spec.color.x) * k, spec.color.y + (1 - spec.color.y) * k,
        spec.color.z + (1 - spec.color.z) * k, 1)
      const body = this.factory.makeBox(so, "Body", spec.size, vec3.zero(), bodyColor)
      const glowRmv = this.factory.makeBox(so, "Glow", spec.size.add(new vec3(5, 5, 5)), vec3.zero(), this.glowColor, true)
      const labels = so.createComponent(StackRightCartonLabelUI.getTypeName()) as StackRightCartonLabelUI
      labels.setup(spec.name, spec.kg + " kg · " + (spec.fragile ? "FRAGILE" : "HEAVY"), spec.size)

      const col = so.createComponent("Physics.ColliderComponent") as ColliderComponent
      const shape = Shape.createBoxShape()
      shape.size = spec.size
      col.shape = shape
      const interactable = so.createComponent(Interactable.getTypeName()) as Interactable
      const manip = so.createComponent(InteractableManipulation.getTypeName()) as InteractableManipulation
      manip.setCanRotate(false)
      manip.setCanScale(false)

      this.cases.push({
        index: i, spec, so,
        home: so.getTransform().getWorldPosition(),
        placed: false, grabbed: false, returning: false, returnFrom: vec3.zero(), returnT: 0, hovered: false,
        interactable, manip,
        bodyMat: body.mainMaterial,
        bodyColor,
        glow: glowRmv.getSceneObject(),
        glowMat: glowRmv.mainMaterial,
      })
    }
    for (let k = ORDER.length; k < this.pickList.getChildrenCount(); k++) this.pickList.getChild(k).enabled = false
  }

  private buildAudio(): void {
    const tracks: {[k: string]: AudioTrackAsset} = {chime: SFX_CHIME, snap: SFX_SNAP, mistake: SFX_MISTAKE, complete: SFX_COMPLETE}
    for (const k of Object.keys(tracks)) {
      const so = global.scene.createSceneObject("Sfx_" + k)
      so.setParent(this.sceneObject)
      const a = so.createComponent("Component.AudioComponent") as AudioComponent
      a.audioTrack = tracks[k]
      a.playbackMode = Audio.PlaybackMode.LowLatency
      a.volume = 0.8
      this.audio[k] = a
    }
  }

  private play(k: string): void {
    const a = this.audio[k]
    if (!a) return
    if (a.isPlaying()) a.stop(false)
    a.play(1)
  }

  private log(msg: string): void {
    if (this.debugLogs) print("[StackRight] " + msg)
  }

  private validateRefs(): boolean {
    const missing: string[] = []
    const refs: {[k: string]: any} = {
      pallet: this.pallet, shelfBay: this.shelfBay, pickList: this.pickList, ghost: this.ghost,
      offViewArrow: this.offViewArrow, resetPost: this.resetPost, ghostTag: this.ghostTag, counter: this.counter,
      tipText: this.tipText, completionCard: this.completionCard, resetButton: this.resetButton,
      boxMesh: this.boxMesh, baseMaterial: this.baseMaterial,
    }
    for (const k of Object.keys(refs)) if (isNull(refs[k])) missing.push(k)
    if (missing.length > 0) {
      print("[StackRight] ERROR: unwired @input(s): " + missing.join(", "))
      return false
    }
    return true
  }
}

// StackRightTestDriver.ts
// TEST/DEMO ONLY. Drives the controller through its test hooks (simulateGrab / simulateRelease /
// pressReset, the same code path as real SIK grabs) a moment after the Lens starts.
//   mode "off"       - does nothing (normal play)
//   mode "selftest"  - checks done criteria 1-6 (full 30-case run), prints "[StackRightTest] PASS/FAIL ..." lines
//   mode "ghost"     - 14 cases placed (layers 1-2 + 2 of layer 3), case 15 held above the pallet: ghost + tag
//   mode "overhang"  - case 1 dropped hanging over the pallet edge: red overhang tip showing
//   mode "layerdone" - layer 1 finished: white "Layer 1 done" note showing
//   mode "complete"  - all 30 placed: completion card showing
//   mode "paced"     - real-time run with pauses, for screenshots
//   mode "demo"      - scripted run for the demo video: every case carried along an arc from the
//                      pick face to its drop point, one overhang and one gap mistake, Reset at the
//                      end; prints "[DEMO] <beat>" at the start of each beat
// Expects: the StackRightController component. Must not: change game rules.
import WorldCameraFinderProvider from "SpectaclesInteractionKit.lspkg/Providers/CameraProvider/WorldCameraFinderProvider"
import {StackRightController, TIP_GAP, TIP_OVERHANG} from "./StackRightController"
import {ORDER, PLAN, ghostTagText, layerDoneText, plannedSize, footprint, HEIGHT_LIMIT_CM, STACK_HEIGHT_CM, LAYER_COUNT} from "./StackRightPickList"

@component
export class StackRightTestDriver extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightTestDriver – test/demo states (set mode to off for normal play)</span>')
  @ui.separator
  @input
  @hint("The StackRightController to drive")
  controller: StackRightController

  @input
  @hint("off | selftest | ghost | overhang | layerdone | complete | paced | demo")
  @widget(new ComboBoxWidget([
    new ComboBoxItem("off", "off"),
    new ComboBoxItem("selftest", "selftest"),
    new ComboBoxItem("ghost", "ghost"),
    new ComboBoxItem("overhang", "overhang"),
    new ComboBoxItem("layerdone", "layerdone"),
    new ComboBoxItem("complete", "complete"),
    new ComboBoxItem("paced", "paced"),
    new ComboBoxItem("demo", "demo"),
  ]))
  mode: string = "off"

  @input
  @hint("Seconds to wait after start before driving")
  startDelaySec: number = 1.5

  @input
  @hint("demo only: hold the camera at a fixed recording viewpoint (device tracking off for the run)")
  demoCamera: boolean = true

  @input
  @hint("demo only: camera eye, pallet-local cm (x right, y up from the floor, z toward the user)")
  demoEye: vec3 = new vec3(-60, 165, 480)

  @input
  @hint("demo only: point the camera looks at, pallet-local cm")
  demoLookAt: vec3 = new vec3(57, 72, -40)

  private passed = 0
  private failed = 0
  private dcResults: {[dc: string]: [number, number]} = {}

  onAwake(): void {
    if (this.mode === "off") return
    this.createEvent("OnStartEvent").bind(() => {
      this.wait(this.startDelaySec).then(() => this.runMode())
    })
  }

  private async runMode(): Promise<void> {
    const c = this.controller
    print("[StackRightTest] mode = " + this.mode)
    if (this.mode === "selftest") {
      await this.selfTest()
    } else if (this.mode === "ghost") {
      for (let i = 0; i < 14; i++) this.dropOnSlot(i)
      await this.settle()
      c.simulateGrab(14)
      // Hold the case in the air in front of its slot, as if carried there.
      const held = c.getSlotWorldPosition(14).add(new vec3(25, 45, 45))
      c.pickList.getChild(14).getTransform().setWorldPosition(held)
    } else if (this.mode === "overhang") {
      c.tipDurationSec = 120 // demo only: keep the tip up long enough to frame a screenshot
      this.dropOnSlot(0)
      c.simulateGrab(1)
      c.simulateRelease(1, this.palletPoint(48, 40, -29))
    } else if (this.mode === "layerdone") {
      c.tipDurationSec = 120
      for (let i = 0; i < 6; i++) this.dropOnSlot(i)
    } else if (this.mode === "complete") {
      for (let i = 0; i < ORDER.length; i++) this.dropOnSlot(i)
    } else if (this.mode === "demo") {
      await this.demo()
    } else if (this.mode === "paced") {
      // Real-time run: 3 cases held over their ghost then dropped, with pauses, one gap drop, then the rest.
      c.tipDurationSec = 120
      for (let i = 0; i < 3; i++) {
        c.simulateGrab(i)
        c.pickList.getChild(i).getTransform().setWorldPosition(c.getSlotWorldPosition(i).add(new vec3(0, 30, 0)))
        print("[StackRightTest] paced: holding case " + i + " over its ghost")
        await this.wait(6)
        c.simulateRelease(i, c.getSlotWorldPosition(i).add(new vec3(0, 5, 0)))
        await this.wait(3)
      }
      c.simulateGrab(3)
      c.simulateRelease(3, this.palletPoint(0, 45, 10))
      print("[StackRightTest] paced: gap drop, tip '" + c.getTipText().replace(/\n/g, " | ") + "'")
      await this.wait(8)
      await this.settle()
      const last = ORDER.length - 1
      for (let i = 3; i < last; i++) this.dropOnSlot(i)
      c.simulateGrab(last)
      c.pickList.getChild(last).getTransform().setWorldPosition(c.getSlotWorldPosition(last).add(new vec3(0, 30, 0)))
      print("[StackRightTest] paced: holding case " + last + " over its ghost (layer 5)")
      await this.wait(8)
      c.simulateRelease(last, c.getSlotWorldPosition(last).add(new vec3(0, 5, 0)))
      print("[StackRightTest] paced: card '" + c.getCompletionText().split("\n").join(" | ") + "'")
    }
  }

  // ---------------------------------------------------------------------------------------
  // Demo: the scripted run recorded for the demo video. Every grab and release goes through the
  // controller's test hooks, so the rules are the real ones; only the carry in between is animated.
  // ---------------------------------------------------------------------------------------
  private async demo(): Promise<void> {
    const c = this.controller
    c.reset()
    if (this.demoCamera) this.setDemoCamera()
    const layerCases = (layer: number): number[] => {
      const out: number[] = []
      for (let i = 0; i < PLAN.length; i++) if (PLAN[i].layer === layer) out.push(i)
      return out
    }

    this.beat("intro")
    await this.wait(4)

    this.beat("case1")
    await this.demoPlace(0, 3, 1.5, 0.4)
    await this.wait(1.5)

    // Case 2 hangs ~15 cm over the side edge nearest the pick face, in the near row.
    this.beat("overhang")
    await this.settle()
    const fp = footprint(ORDER[1], PLAN[1].turned)
    const deckY = PLAN[1].center.y + 3
    c.simulateGrab(1)
    await this.carry(1, this.palletPoint(58.25 + 15 - fp.x / 2, deckY, PLAN[3].center.z), 2.5)
    c.simulateRelease(1, this.caseWorld(1))
    await this.wait(3.5)

    // Case 2 dropped on the near-left slot, well inside the edge but far from its own ghost.
    this.beat("gap")
    await this.settle()
    c.simulateGrab(1)
    await this.carry(1, this.palletPoint(PLAN[3].center.x, deckY, PLAN[3].center.z), 2.5)
    c.simulateRelease(1, this.caseWorld(1))
    await this.wait(3.5)

    this.beat("case2")
    await this.settle()
    await this.demoPlace(1, 2, 0.3, 0.3)

    this.beat("layer1")
    for (const i of layerCases(1).slice(2)) await this.demoPlaceTimed(i, 1.4)
    await this.wait(3.5)

    this.beat("layer2turn")
    const l2 = layerCases(2)
    await this.demoPlace(l2[0], 3, 1.5, 0.4)
    for (const i of l2.slice(1)) await this.demoPlaceTimed(i, 0.9)

    this.beat("fast")
    for (const i of layerCases(3).concat(layerCases(4))) await this.demoPlaceTimed(i, 0.5)

    this.beat("layer5")
    for (const i of layerCases(5)) await this.demoPlaceTimed(i, 1.4)

    this.beat("complete")
    print("[DEMO] card '" + c.getCompletionText().replace(/\n/g, " | ") + "'")
    await this.wait(7)

    this.beat("reset")
    c.pressReset()
    await this.wait(3)

    this.beat("end")
  }

  private beat(name: string): void {
    print("[DEMO] " + name)
  }

  /** Fixed recording viewpoint: device tracking off for this run only (the next preview start restores it). */
  private setDemoCamera(): void {
    const camSo = WorldCameraFinderProvider.getInstance().getComponent().getSceneObject()
    const tracking = camSo.getComponent("Component.DeviceTracking")
    if (tracking) tracking.enabled = false
    const eye = this.palletPoint(this.demoEye.x, this.demoEye.y, this.demoEye.z)
    const look = this.palletPoint(this.demoLookAt.x, this.demoLookAt.y, this.demoLookAt.z)
    const t = camSo.getTransform()
    t.setWorldPosition(eye)
    t.setWorldRotation(quat.lookAt(eye.sub(look).normalize(), vec3.up())) // camera looks down its -Z
    print("[DEMO] camera eye " + this.v(eye) + " looking at " + this.v(look))
  }

  /** Grab, carry to just above the ghost, hover, lower and release onto the slot (snaps). */
  private async demoPlace(i: number, carrySec: number, hoverSec: number, lowerSec: number): Promise<void> {
    const c = this.controller
    const slot = c.getSlotWorldPosition(i)
    c.simulateGrab(i)
    // Hover high enough that the held case does not cover the ghost tag; quick placements stay low.
    const lift = hoverSec > 0 ? 45 : 25
    await this.carry(i, slot.add(new vec3(0, lift, 0)), carrySec)
    if (hoverSec > 0) await this.wait(hoverSec)
    await this.carry(i, slot.add(new vec3(0, 3, 0)), lowerSec, false)
    c.simulateRelease(i, this.caseWorld(i))
  }

  /** One case in a fixed total time: 70% carry, 15% lower, 15% rest. */
  private async demoPlaceTimed(i: number, totalSec: number): Promise<void> {
    await this.demoPlace(i, totalSec * 0.7, 0, totalSec * 0.15)
    await this.wait(totalSec * 0.15)
  }

  private caseWorld(i: number): vec3 {
    return this.controller.pickList.getChild(i).getTransform().getWorldPosition()
  }

  /**
   * Moves held case i to `to` over `sec`, eased in/out. With `arc`, the path rises to about 30 cm
   * above the stack top (bottom of the case), so the ghost below stays visible during the carry.
   */
  private carry(i: number, to: vec3, sec: number, arc: boolean = true): Promise<void> {
    const t = this.controller.pickList.getChild(i).getTransform()
    const from = t.getWorldPosition()
    const peak = Math.max(this.controller.getFloorWorldY() + this.controller.getStackTopCm() + 30 + ORDER[i].size.y / 2,
      Math.max(from.y, to.y) + 10)
    const ctrlY = arc ? 2 * peak - (from.y + to.y) / 2 : (from.y + to.y) / 2 // quadratic: midpoint reaches peak
    const start = getTime()
    return new Promise((resolve) => {
      const ev = this.createEvent("UpdateEvent")
      ev.bind(() => {
        const u = sec > 0 ? Math.min(1, (getTime() - start) / sec) : 1
        const e = u < 0.5 ? 4 * u * u * u : 1 - Math.pow(-2 * u + 2, 3) / 2 // ease in/out cubic
        const y = (1 - e) * (1 - e) * from.y + 2 * (1 - e) * e * ctrlY + e * e * to.y
        t.setWorldPosition(new vec3(from.x + (to.x - from.x) * e, y, from.z + (to.z - from.z) * e))
        if (u >= 1) {
          this.removeEvent(ev)
          resolve()
        }
      })
    })
  }

  // ---------------------------------------------------------------------------------------
  // Self-test: one block per done criterion in devpost/design-brief.md
  // ---------------------------------------------------------------------------------------
  private async selfTest(): Promise<void> {
    const c = this.controller
    const N = ORDER.length
    c.reset()
    await this.wait(0.3)

    // DC1: pallet on the floor ~1 m ahead at real size, pick face ~1.4 m right with the first 4
    // cases, height-limit outline at 180 cm.
    const cam = c.getCameraWorldPosition()
    const pallet = c.getPalletWorldPosition()
    const shelf = c.getShelfWorldPosition()
    this.check("DC1", "pallet ~100 cm ahead (got " + (cam.z - pallet.z).toFixed(0) + ")", cam.z - pallet.z >= 80 && cam.z - pallet.z <= 120)
    this.check("DC1", "pallet centred (dx " + (pallet.x - cam.x).toFixed(0) + ")", Math.abs(pallet.x - cam.x) < 20)
    this.check("DC1", "pallet on floor, " + (cam.y - pallet.y).toFixed(0) + " cm below eyes", cam.y - pallet.y >= 140 && cam.y - pallet.y <= 170)
    this.check("DC1", "shelf ~140 cm right (got " + (shelf.x - cam.x).toFixed(0) + ")", shelf.x - cam.x >= 120 && shelf.x - cam.x <= 160)
    this.check("DC1", N + " cases in the order (got " + c.getCaseCount() + ")", c.getCaseCount() === 30)
    this.check("DC1", "queue shows exactly cases 0-3", this.queueOk(0))
    let lowerShelf = true
    for (let i = 0; i < 4; i++) {
      const p = c.getCaseWorldPosition(i)
      const bottom = p.y - ORDER[i].size.y / 2 - c.getFloorWorldY()
      if (Math.abs(bottom - 40) > 0.5 || Math.abs(p.x - shelf.x) > 1) lowerShelf = false
    }
    this.check("DC1", "queue sits on the lower shelf (bottom 40 cm)", lowerShelf)
    let nearest = true
    const d0 = this.flatDist(c.getCaseWorldPosition(0), pallet)
    for (let i = 1; i < 4; i++) if (this.flatDist(c.getCaseWorldPosition(i), pallet) <= d0) nearest = false
    this.check("DC1", "case due now is in the slot nearest the pallet (" + d0.toFixed(0) + " cm)", nearest)
    const limitAbove = c.getHeightLimitWorldY() - c.getFloorWorldY()
    this.check("DC1", "height-limit outline " + limitAbove.toFixed(1) + " cm above the floor, visible",
      Math.abs(limitAbove - HEIGHT_LIMIT_CM) < 0.5 && c.isHeightLimitVisible())
    this.check("DC1", "counter reads '" + c.getCounterText() + "'", c.getCounterText() === "Layer 1 · 0 / 30")
    this.check("DC1", "case 0 glows, only case 0 interactable", c.isCaseGlowing(0) && this.onlyInteractable(0))

    // DC2: grabbing the case due now shows its ghost in the planned slot, turned to the layer, with the tag.
    c.simulateGrab(1)
    this.check("DC2", "grabbing a later case does nothing (no ghost)", !c.isGhostVisible() && c.getGrabbedIndex() === -1)
    this.check("DC2", "no ghost before grab", !c.isGhostVisible())
    c.simulateGrab(0)
    this.check("DC2", "ghost visible after grabbing case 0", c.isGhostVisible())
    this.check("DC2", "ghost sits on case 0's planned slot", c.getGhostWorldPosition().distance(c.getSlotWorldPosition(0)) < 0.5)
    this.check("DC2", "layer-1 ghost size = case size " + this.v(c.getGhostSize()), c.getGhostSize().distance(ORDER[0].size) < 0.01)
    this.check("DC2", "tag reads '" + c.getGhostTagText() + "'", c.isGhostTagVisible() && c.getGhostTagText() === "Layer 1 · 1 of 30 · 17 kg")

    // DC3: drop within 15 cm snaps, counter goes up, queue moves up, next case glows.
    c.simulateRelease(0, c.getSlotWorldPosition(0).add(new vec3(10, 5, 0)))
    this.check("DC3", "case 0 snapped (dropped 10 cm off)", c.isCasePlaced(0))
    this.check("DC3", "snapped square onto the slot", c.getCaseWorldPosition(0).distance(c.getSlotWorldPosition(0)) < 0.5 &&
      this.angleDeg(c.getCaseWorldRotation(0), c.getSlotWorldRotation(0)) < 0.5)
    this.check("DC3", "counter reads '" + c.getCounterText() + "'", c.getCounterText() === "Layer 1 · 1 / 30")
    this.check("DC3", "ghost hidden after placing", !c.isGhostVisible() && !c.isGhostTagVisible())
    this.check("DC3", "queue moved up: cases 1-4 shown, 5+ hidden", this.queueOk(1))
    this.check("DC3", "case 1 sliding to the front slot", c.isCaseReturning(1) &&
      c.getCaseHomePosition(1).distance(c.getQueueSlotWorldPosition(0, 1)) < 0.5)
    await this.settle()
    this.check("DC3", "case 1 now in the front slot, case 4 at the back", c.getCaseWorldPosition(1).distance(c.getQueueSlotWorldPosition(0, 1)) < 0.5 &&
      c.getCaseWorldPosition(4).distance(c.getQueueSlotWorldPosition(3, 4)) < 0.5)
    this.check("DC3", "next case (1) glows and is the only one interactable", c.isCaseGlowing(1) && !c.isCaseGlowing(0) && this.onlyInteractable(1))

    // DC4: on the pallet but off the ghost -> back + red tip (overhang / gap) + mistake; off the pallet -> back, no mistake.
    let m = c.getMistakes()
    c.simulateGrab(1)
    c.simulateRelease(1, this.palletPoint(0, 45, 10)) // 39 cm from the ghost, fully inside the edge
    this.check("DC4", "gap drop: not placed, sliding back", !c.isCasePlaced(1) && c.isCaseReturning(1))
    this.check("DC4", "gap drop: tip '" + c.getTipText().replace(/\n/g, " | ") + "'", c.isTipVisible() && c.getTipKind() === "gap" && c.getTipText() === TIP_GAP)
    this.check("DC4", "gap drop: one mistake", c.getMistakes() === m + 1)
    await this.settle()
    this.check("DC4", "case back home on the pick face", c.getCaseWorldPosition(1).distance(c.getCaseHomePosition(1)) < 0.5)
    c.simulateGrab(1)
    c.simulateRelease(1, this.palletPoint(48, 45, -29)) // 38 cm wide case centred 48 cm out: 9 cm over the edge
    this.check("DC4", "overhang drop: tip '" + c.getTipText().replace(/\n/g, " | ") + "'", c.isTipVisible() && c.getTipKind() === "overhang" && c.getTipText() === TIP_OVERHANG)
    this.check("DC4", "overhang drop: one more mistake", c.getMistakes() === m + 2 && !c.isCasePlaced(1))
    await this.settle()
    c.simulateGrab(1)
    c.simulateRelease(1, this.palletPoint(40, 45, 10)) // 40 + 19 = 59 cm: 0.75 cm over, inside the 2 cm tolerance
    this.check("DC4", "drop 0.75 cm over the edge counts as gap, not overhang", c.getTipKind() === "gap" && c.getMistakes() === m + 3)
    await this.settle()
    c.simulateGrab(1)
    c.simulateRelease(1, this.palletPoint(0, 30, 90)) // on the floor in front of the pallet
    this.check("DC4", "off-pallet drop: back, no mistake", !c.isCasePlaced(1) && c.isCaseReturning(1) && c.getMistakes() === m + 3)
    await this.settle()
    this.check("DC4", "case back home after off-pallet drop", c.getCaseWorldPosition(1).distance(c.getCaseHomePosition(1)) < 0.5)
    await this.wait(this.controller.tipDurationSec + 0.3)
    this.check("DC4", "tip hides after ~4 s", !c.isTipVisible())

    // DC5 + DC6: build the rest; layer notes after layers 1-4; layers 2/4 turned vs 1/3; queue shifts every time.
    let queueFails = 0
    let snapFails = 0
    for (let i = 1; i < N; i++) {
      if (i === 6) {
        // Turned layer: the ghost is the case with x/z swapped, and an overhang is judged in that orientation.
        c.simulateGrab(6)
        const want = plannedSize(ORDER[6], true)
        this.check("DC2", "layer-2 ghost turned: size " + this.v(c.getGhostSize()) + " = " + this.v(want),
          c.getGhostSize().distance(want) < 0.01 && c.getGhostSize().x !== ORDER[6].size.x)
        this.check("DC2", "layer-2 tag reads '" + c.getGhostTagText() + "'", c.getGhostTagText() === "Layer 2 · 7 of 30 · 14 kg")
        m = c.getMistakes()
        c.simulateRelease(6, this.palletPoint(35, 80, 0)) // turned: 35 + 29 = 64 over; unturned it would fit
        this.check("DC4", "overhang judged in the planned (turned) orientation", c.getTipKind() === "overhang" && c.getMistakes() === m + 1)
        await this.settle()
      }
      if (i === 14) {
        c.simulateGrab(14)
        this.check("DC2", "case 15 tag reads '" + c.getGhostTagText() + "'", c.getGhostTagText() === "Layer 3 · 15 of 30 · 10 kg")
        this.check("DC2", "layer-3 ghost not turned", c.getGhostSize().distance(ORDER[14].size) < 0.01)
      }
      const layer = PLAN[i].layer
      this.dropOnSlot(i)
      if (!c.isCasePlaced(i) || c.getCaseWorldPosition(i).distance(c.getSlotWorldPosition(i)) > 0.5 ||
        this.angleDeg(c.getCaseWorldRotation(i), c.getSlotWorldRotation(i)) > 0.5) snapFails++
      if (i + 1 < N && !this.queueOk(i + 1)) queueFails++
      const lastOfLayer = i === N - 1 || PLAN[i + 1].layer !== layer
      if (lastOfLayer && layer < LAYER_COUNT) {
        this.check("DC5", "layer " + layer + " done note: '" + c.getTipText().replace(/\n/g, " | ") + "'",
          c.isTipVisible() && c.getTipKind() === "layer" && c.getTipText() === layerDoneText(layer))
      }
      if (lastOfLayer && layer === LAYER_COUNT) {
        this.check("DC5", "no 'turns 90°' note after the last layer", c.getTipKind() !== "layer")
      }
    }
    this.check("DC3", "every case snapped onto its slot with the planned rotation (" + snapFails + " misses)", snapFails === 0)
    this.check("DC3", "queue moved up after every placement (" + queueFails + " misses)", queueFails === 0)

    // Orientation: each layer-2/4 case is 90 deg from layer 1/3 cases about up.
    for (const [a, b] of [[0, 6], [6, 12], [12, 20]]) {
      const ang = this.angleDeg(c.getCaseWorldRotation(a), c.getCaseWorldRotation(b))
      this.check("DC5", "layer " + PLAN[a].layer + " vs layer " + PLAN[b].layer + " placed " + ang.toFixed(1) + "° apart", Math.abs(ang - 90) < 0.5)
    }
    let allTurned = true
    for (let i = 0; i < N; i++) if (PLAN[i].turned !== (PLAN[i].layer === 2 || PLAN[i].layer === 4)) allTurned = false
    this.check("DC5", "plan turns exactly layers 2 and 4", allTurned)
    this.logJoints()

    // DC6: completion card + Reset.
    this.check("DC6", "all 30 placed, counter '" + c.getCounterText() + "'", c.isComplete() && c.getCounterText() === "Layer 5 · 30 / 30")
    this.check("DC6", "stack top " + c.getStackTopCm().toFixed(1) + " cm (~157), under the 180 cm limit",
      Math.abs(c.getStackTopCm() - 157) < 0.5 && Math.abs(STACK_HEIGHT_CM - 157) < 0.5 && c.getStackTopCm() < HEIGHT_LIMIT_CM)
    const card = c.getCompletionText()
    this.check("DC6", "completion card visible", c.isCompletionVisible())
    this.check("DC6", "card: '" + card.replace(/\n/g, " | ") + "'",
      card.indexOf("Pallet done! 30 cases · 5 layers · 157 cm\n") === 0 && /\nTime \d+:\d\d · Mistakes /.test(card) &&
      card.indexOf("Mistakes " + c.getMistakes()) >= 0 && card.indexOf("\nWrap and label the pallet.") >= 0)
    this.check("DC6", "card groups mistakes by rule (" + c.getOverhangMistakes() + " overhang, " + c.getGapMistakes() + " gap)",
      c.getOverhangMistakes() + c.getGapMistakes() === c.getMistakes() &&
      (c.getOverhangMistakes() === 0 || card.indexOf(c.getOverhangMistakes() + " overhang") >= 0) &&
      (c.getGapMistakes() === 0 || card.indexOf(c.getGapMistakes() + " gap") >= 0))
    await this.wait(1)
    this.check("DC6", "card stays up", c.isCompletionVisible())
    c.pressReset()
    let allClear = true
    for (let i = 0; i < N; i++) if (c.isCasePlaced(i)) allClear = false
    this.check("DC6", "Reset: pallet cleared", allClear)
    this.check("DC6", "Reset: order restarts, first 4 cases on the pick face", this.queueOk(0) && c.getNextIndex() === 0)
    this.check("DC6", "Reset: counter '" + c.getCounterText() + "', card hidden, mistakes 0",
      c.getCounterText() === "Layer 1 · 0 / 30" && !c.isCompletionVisible() && c.getMistakes() === 0)
    this.check("DC6", "Reset: case 0 glows and is interactable", c.isCaseGlowing(0) && this.onlyInteractable(0))

    print("[StackRightTest] SUMMARY per done criterion:")
    for (const dc of Object.keys(this.dcResults).sort()) {
      const [p, f] = this.dcResults[dc]
      print("[StackRightTest]   " + dc + ": " + (f === 0 ? "PASS" : "FAIL") + " (" + p + " passed, " + f + " failed)")
    }
    print("[StackRightTest] DONE: " + this.passed + " passed, " + this.failed + " failed")
  }

  // ---------------------------------------------------------------------------------------
  /** Cases next..next+3 shown on the pick face (homes = queue slots); every other unplaced case hidden. */
  private queueOk(next: number): boolean {
    const c = this.controller
    for (let i = 0; i < c.getCaseCount(); i++) {
      if (c.isCasePlaced(i)) continue
      const q = i - next
      const inQueue = q >= 0 && q < c.getQueueSize()
      if (c.isCaseShown(i) !== inQueue) return false
      if (inQueue && c.getCaseHomePosition(i).distance(c.getQueueSlotWorldPosition(q, i)) > 0.5) return false
    }
    return true
  }

  private onlyInteractable(i: number): boolean {
    const c = this.controller
    for (let k = 0; k < c.getCaseCount(); k++) if (c.isCaseInteractable(k) !== (k === i)) return false
    return true
  }

  /** Prints which joint lines (cm, pallet axes) each pair of neighbouring layers share. */
  private logJoints(): void {
    const joints = (layer: number, axis: "x" | "z"): number[] => {
      const out: number[] = []
      for (let i = 0; i < PLAN.length; i++) {
        if (PLAN[i].layer !== layer) continue
        const fp = footprint(ORDER[i], PLAN[i].turned)
        const half = axis === "x" ? fp.x / 2 : fp.y / 2
        const ctr = axis === "x" ? PLAN[i].center.x : PLAN[i].center.z
        for (const e of [ctr - half, ctr + half]) {
          const r = Math.round(e * 10) / 10
          if (Math.abs(r) < 55 && out.indexOf(r) < 0) out.push(r)
        }
      }
      return out.sort((a, b) => a - b)
    }
    for (let l = 1; l < LAYER_COUNT; l++) {
      const shared: string[] = []
      for (const axis of ["x", "z"] as ("x" | "z")[]) {
        const lo = joints(l, axis), hi = joints(l + 1, axis)
        for (const j of lo) if (hi.indexOf(j) >= 0) shared.push(axis + "=" + j)
      }
      print("[StackRightTest] INFO joints shared by layers " + l + " and " + (l + 1) + ": " + (shared.length ? shared.join(", ") : "none"))
    }
  }

  private palletPoint(x: number, y: number, z: number): vec3 {
    return this.controller.getPalletWorldTransform().multiplyPoint(new vec3(x, y, z))
  }

  private dropOnSlot(i: number): void {
    this.controller.simulateGrab(i)
    this.controller.simulateRelease(i, this.controller.getSlotWorldPosition(i).add(new vec3(0, 5, 0)))
  }

  private flatDist(a: vec3, b: vec3): number {
    return Math.sqrt((a.x - b.x) * (a.x - b.x) + (a.z - b.z) * (a.z - b.z))
  }

  private angleDeg(a: quat, b: quat): number {
    const d = Math.abs(a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w)
    return 2 * Math.acos(Math.min(1, d)) * 180 / Math.PI
  }

  private v(p: vec3): string {
    return "(" + p.x.toFixed(0) + ", " + p.y.toFixed(0) + ", " + p.z.toFixed(0) + ")"
  }

  private check(dc: string, what: string, ok: boolean): void {
    if (ok) this.passed++
    else this.failed++
    const r = this.dcResults[dc] || [0, 0]
    r[ok ? 0 : 1]++
    this.dcResults[dc] = r
    print("[StackRightTest] " + (ok ? "PASS" : "FAIL") + " " + dc + ": " + what)
  }

  private async settle(): Promise<void> {
    for (let k = 0; k < 30; k++) {
      let busy = false
      for (let i = 0; i < this.controller.getCaseCount(); i++) if (this.controller.isCaseReturning(i)) busy = true
      if (!busy) return
      await this.wait(0.1)
    }
  }

  private wait(sec: number): Promise<void> {
    return new Promise((resolve) => {
      const ev = this.createEvent("DelayedCallbackEvent")
      ev.bind(() => resolve())
      ev.reset(sec)
    })
  }
}

// StackRightCartonLabelUI.ts
// Owns: the printed labels on one carton (name + "14 kg · HEAVY" / "FRAGILE") on the faces the
// user sees: the side facing the pallet (-X, seen while the carton is on the shelf), the near
// side (+Z, seen on the pallet) and the top. Created at runtime by the controller on each carton.
// Must not: hold game state.

@component
export class StackRightCartonLabelUI extends BaseScriptComponent {
  @ui.label('<span style="color: #60A5FA;">StackRightCartonLabelUI – printed carton labels</span>')
  @ui.separator

  @ui.label('<span style="color: #60A5FA;">Settings</span>')
  @ui.group_start("Settings")
  @input
  @hint("Label text size (about 44 = 1 cm em height)")
  @widget(new SliderWidget(40, 300, 1))
  labelSize: number = 120

  @ui.group_end

  setup(name: string, detail: string, size: vec3): void {
    const hx = size.x / 2, hy = size.y / 2, hz = size.z / 2
    const off = 0.3
    // -X face (seen from the pallet side while on the shelf): +Z normal rotated to -X
    this.face("LabelSide", name, detail, new vec3(-hx - off, 0, 0), quat.angleAxis(-Math.PI / 2, vec3.up()), size.z, size.y)
    // +Z face (near side on the pallet)
    this.face("LabelFront", name, detail, new vec3(0, 0, hz + off), quat.quatIdentity(), size.x, size.y)
    // top face, readable from the user's side
    this.face("LabelTop", name, detail, new vec3(0, hy + off, 0), quat.angleAxis(-Math.PI / 2, vec3.right()), size.x, size.z)
  }

  private face(objName: string, name: string, detail: string, pos: vec3, rot: quat, w: number, h: number): void {
    const so = global.scene.createSceneObject(objName)
    so.setParent(this.sceneObject)
    so.getTransform().setLocalPosition(pos)
    so.getTransform().setLocalRotation(rot)
    const t = so.createComponent("Component.Text") as Text
    t.text = name + "\n" + detail
    t.size = this.labelSize
    t.depthTest = true
    t.textFill.color = new vec4(1, 1, 1, 1)
    t.horizontalAlignment = HorizontalAlignment.Center
    t.verticalAlignment = VerticalAlignment.Center
    t.horizontalOverflow = HorizontalOverflow.Shrink
    t.verticalOverflow = VerticalOverflow.Shrink
    const hw = w / 2 - 2
    const hh = h / 2 - 2
    t.layoutRect = Rect.create(-hw, hw, -hh, hh)
  }
}

