      c.manip.onManipulationStart.add(() => this.handleGrab(i))
      c.manip.onManipulationEnd.add(() => this.handleRelease(i, c.so.getTransform().getWorldPosition()))
      c.interactable.onHoverEnter.add(() => this.setHover(i, true))
