      c.grabbed = false
      c.returning = false
      c.hovered = false
      c.so.getTransform().setWorldRotation(quat.quatIdentity())
      c.bodyMat.mainPass.baseColor = c.bodyColor
    }
    this.nextIndex = 0
    this.placedCount = 0
    this.mistakes = 0
    this.overhangMistakes = 0
    this.gapMistakes = 0
